/// The fields `Utensil` declares, by their wire names.
pub const UTENSIL_FIELDS: &[&str] = &["id", "recipe", "name", "entityKey", "ref", "deletedOnRef", "_version"];

/// Validates a JSON value as `Utensil`. A null value passes; the errors
/// are empty when the value is valid.
pub fn validate_utensil(value: &Value) -> ValidationErrors {
    let mut errors = ValidationErrors::new();
    if value.is_null() {
        return errors;
    }
    {
        let field = value.get("id");
        errors.set_result("id", scalars::validate_identity_uuid_required(field));
    }
    {
        let field = value.get("recipe");
        if let Some(nested) = field {
            rt::check_nested(&mut errors, "recipe".to_owned(), nested, validate_recipe);
        }
        if rt::is_absent(field) {
            errors.push("recipe", ValidationError::required());
        }
    }
    {
        let field = value.get("name");
        if rt::is_absent(field) {
            errors.push("name", ValidationError::required());
        }
        rt::expect_string(&mut errors, "name", field);
    }
    {
        let field = value.get("entityKey");
        if !rt::is_absent(field) {
            errors.set_result("entityKey", scalars::validate_identity_uuid(field));
        }
    }
    {
        let field = value.get("ref");
        if let Some(nested) = field {
            rt::check_nested(&mut errors, "ref".to_owned(), nested, validate_recipe_ref);
        }
        if rt::is_absent(field) {
            errors.push("ref", ValidationError::required());
        }
    }
    {
        let field = value.get("deletedOnRef");
        if rt::is_absent(field) {
            errors.push("deletedOnRef", ValidationError::required());
        }
        rt::expect_boolean(&mut errors, "deletedOnRef", field);
    }
    {
        let field = value.get("_version");
        rt::expect_number(&mut errors, "_version", field);
    }
    errors
}

/// Validates a `Utensil` object that must be present: its errors are one
/// `object` error.
pub fn validate_utensil_required(value: Option<&Value>) -> rt::ScalarResult {
    rt::require_object(value, validate_utensil)
}

/// Prepares a JSON value as `Utensil`: fills its `@default` values,
/// refuses undeclared keys when asked and validates it, returning the value
/// `parse_utensil` decodes.
pub fn prepare_utensil(value: Value, unknown_fields: rt::UnknownFields) -> Result<Value, rt::ParseError> {
    let Value::Object(mut object) = value else {
        return Err(rt::ParseError::NotAnObject);
    };
    rt::fill_default(&mut object, "deletedOnRef", "false", true);
    rt::check_unknown_fields(&object, UTENSIL_FIELDS, unknown_fields)?;
    let value = Value::Object(object);
    let errors = validate_utensil(&value);
    if !errors.is_empty() {
        return Err(rt::ParseError::Invalid(errors));
    }
    Ok(value)
}

/// Parses a JSON value as `Utensil`: `prepare_utensil`, then decodes it.
pub fn parse_utensil(value: Value, unknown_fields: rt::UnknownFields) -> Result<crate::types::Utensil, rt::ParseError> {
    let value = prepare_utensil(value, unknown_fields)?;
    serde_json::from_value(value).map_err(rt::ParseError::Decode)
}
